//! VHS tape exporter (<https://github.com/charmbracelet/vhs>). A tape is an input script, so
//! this reproduces what was *typed*; the output is regenerated by VHS.

use std::io::Write;

use mt_record::EventKind;

use crate::{
    ExportError, ExportReport, Exporter, OptKind, OptValue, OptionSpec, Options, Progress,
    Recording, Requires,
};

pub struct Vhs;

/// The marker the recorder writes where echo-off input was dropped (mt_ui `PAUSED_MARKER`).
const PAUSED_MARKER: &str = "input paused (no echo)";

/// Themes the exporter passes through to `Set Theme`; anything else becomes a comment.
const KNOWN_THEMES: &[&str] = &[
    "Dracula",
    "Nord",
    "Tokyo Night",
    "Catppuccin Mocha",
    "Catppuccin Macchiato",
    "Catppuccin Frappe",
    "Catppuccin Latte",
    "Gruvbox Dark",
    "Solarized Dark",
    "Solarized Light",
];

const SHELLS: &[&str] = &[
    "bash", "zsh", "fish", "sh", "dash", "ksh", "tcsh", "csh", "nu", "pwsh", "elvish", "xonsh",
];

/// Pixel metrics for `Set Width`/`Set Height`: a cell is 0.6 em wide and 1.2 em high, plus
/// `PADDING` px on every side.
const CELL_W_EM: f64 = 0.6;
const CELL_H_EM: f64 = 1.2;
const PADDING: u32 = 20;

#[derive(Debug, Clone, PartialEq)]
pub(crate) enum Key {
    Char(char),
    Enter,
    Backspace,
    Tab,
    Up,
    Down,
    Left,
    Right,
    Home,
    End,
    PageUp,
    PageDown,
    Delete,
    Escape,
    Ctrl(char),
    Paste(String),
}

impl Key {
    fn command(&self) -> Option<String> {
        Some(
            match self {
                Key::Enter => "Enter",
                Key::Backspace => "Backspace",
                Key::Tab => "Tab",
                Key::Up => "Up",
                Key::Down => "Down",
                Key::Left => "Left",
                Key::Right => "Right",
                Key::Home => "Home",
                Key::End => "End",
                Key::PageUp => "PageUp",
                Key::PageDown => "PageDown",
                Key::Delete => "Delete",
                Key::Escape => "Escape",
                Key::Ctrl(c) => return Some(format!("Ctrl+{}", c.to_ascii_uppercase())),
                Key::Char(_) | Key::Paste(_) => return None,
            }
            .to_string(),
        )
    }
}

/// Splits recorded input bytes into keys. Keeps bracketed-paste state across calls.
#[derive(Default)]
pub(crate) struct Decoder {
    paste: Option<String>,
}

impl Decoder {
    pub(crate) fn feed(&mut self, s: &str, keys: &mut Vec<Key>, dropped: &mut Vec<String>) {
        let c: Vec<char> = s.chars().collect();
        let mut i = 0;
        while i < c.len() {
            if let Some(buf) = &mut self.paste {
                if c[i..].starts_with(&['\x1b', '[', '2', '0', '1', '~']) {
                    keys.push(Key::Paste(std::mem::take(buf)));
                    self.paste = None;
                    i += 6;
                } else {
                    buf.push(c[i]);
                    i += 1;
                }
                continue;
            }
            match c[i] {
                '\x1b' => i += self.escape(&c[i..], keys, dropped),
                '\r' => {
                    keys.push(Key::Enter);
                    i += 1;
                }
                '\t' => {
                    keys.push(Key::Tab);
                    i += 1;
                }
                '\x7f' => {
                    keys.push(Key::Backspace);
                    i += 1;
                }
                ch @ '\x01'..='\x1a' => {
                    keys.push(Key::Ctrl((b'a' + ch as u8 - 1) as char));
                    i += 1;
                }
                '\0' | '\x1c'..='\x1f' => {
                    dropped.push("control byte".into());
                    i += 1;
                }
                ch => {
                    keys.push(Key::Char(ch));
                    i += 1;
                }
            }
        }
    }

    /// Decodes the escape sequence at the start of `c`; returns how many chars it used.
    fn escape(&mut self, c: &[char], keys: &mut Vec<Key>, dropped: &mut Vec<String>) -> usize {
        match c.get(1) {
            None => {
                keys.push(Key::Escape);
                1
            }
            Some('[') => {
                let mut n = 2;
                while n < c.len() && !('\x40'..='\x7e').contains(&c[n]) {
                    n += 1;
                }
                if n >= c.len() {
                    dropped.push("truncated escape".into());
                    return c.len();
                }
                let params: String = c[2..n].iter().collect();
                let fin = c[n];
                let key = match (params.as_str(), fin) {
                    ("" | "1", 'A') => Some(Key::Up),
                    ("" | "1", 'B') => Some(Key::Down),
                    ("" | "1", 'C') => Some(Key::Right),
                    ("" | "1", 'D') => Some(Key::Left),
                    ("" | "1", 'H') => Some(Key::Home),
                    ("" | "1", 'F') => Some(Key::End),
                    ("1" | "7", '~') => Some(Key::Home),
                    ("4" | "8", '~') => Some(Key::End),
                    ("3", '~') => Some(Key::Delete),
                    ("5", '~') => Some(Key::PageUp),
                    ("6", '~') => Some(Key::PageDown),
                    ("200", '~') => {
                        self.paste = Some(String::new());
                        return n + 1;
                    }
                    _ => None,
                };
                match key {
                    Some(k) => keys.push(k),
                    None => dropped.push(
                        match (params.starts_with('<'), fin) {
                            (true, _) | (false, 'M')
                                if params.starts_with('<') || fin == 'M' && params.is_empty() =>
                            {
                                "mouse report"
                            }
                            (_, 'I' | 'O') if params.is_empty() => "focus report",
                            _ => "unknown CSI",
                        }
                        .into(),
                    ),
                }
                // Legacy mouse reports carry three raw bytes after `ESC [ M`.
                if fin == 'M' && params.is_empty() {
                    return (n + 4).min(c.len());
                }
                n + 1
            }
            Some('O') => match c.get(2) {
                Some(f @ ('A' | 'B' | 'C' | 'D' | 'H' | 'F')) => {
                    keys.push(match f {
                        'A' => Key::Up,
                        'B' => Key::Down,
                        'C' => Key::Right,
                        'D' => Key::Left,
                        'H' => Key::Home,
                        _ => Key::End,
                    });
                    3
                }
                other => {
                    dropped.push("unknown SS3".into());
                    2 + usize::from(other.is_some())
                }
            },
            Some(_) => {
                dropped.push("Alt+key".into());
                2
            }
        }
    }
}

/// Picks quotes for `text` (VHS strings have no escapes): the first of `"`, `'`, `` ` `` the
/// text lacks; text containing all three is split into several strings.
pub(crate) fn quote_segments(text: &str) -> Vec<String> {
    let mut out = Vec::new();
    let mut seg = String::new();
    let flush = |seg: &mut String, out: &mut Vec<String>| {
        if seg.is_empty() {
            return;
        }
        let q = ['"', '\'', '`']
            .into_iter()
            .find(|q| !seg.contains(*q))
            .unwrap_or('"');
        out.push(format!("{q}{seg}{q}"));
        seg.clear();
    };
    for ch in text.chars() {
        let would_have_all = ['"', '\'', '`']
            .iter()
            .all(|q| *q == ch || seg.contains(*q));
        if would_have_all {
            flush(&mut seg, &mut out);
        }
        seg.push(ch);
    }
    flush(&mut seg, &mut out);
    out
}

fn comment(s: &str) -> String {
    format!("# {}", s.replace(['\n', '\r'], " "))
}

struct Tape {
    lines: Vec<String>,
    commands: u64,
    last: Option<f64>,
    min_sleep: f64,
    cap: f64,
}

impl Tape {
    fn cmd(&mut self, line: String) {
        self.lines.push(line);
        self.commands += 1;
    }

    fn note(&mut self, line: &str) {
        self.lines.push(comment(line));
    }

    /// Emits a `Sleep` for the pause before a command at `t`, then marks `t` as the last time.
    fn gap(&mut self, t: f64) {
        if let Some(prev) = self.last {
            let ms = (t - prev) * 1000.0;
            if ms > self.min_sleep {
                self.cmd(format!("Sleep {}ms", ms.min(self.cap).round() as u64));
            }
        }
        self.last = Some(t);
    }
}

impl Exporter for Vhs {
    fn id(&self) -> &'static str {
        "vhs"
    }
    fn label(&self) -> &'static str {
        "VHS tape (.tape)"
    }
    fn extension(&self) -> &'static str {
        "tape"
    }
    fn options(&self) -> Vec<OptionSpec> {
        let int = |key, label, help, min, max, d| OptionSpec {
            key,
            label,
            help,
            kind: OptKind::Int { min, max },
            default: OptValue::Int(d),
        };
        vec![
            int(
                "type_gap_ms",
                "Type gap (ms)",
                "Keys closer than this become one Type",
                1,
                5000,
                150,
            ),
            int(
                "min_sleep_ms",
                "Min sleep (ms)",
                "Shorter gaps emit no Sleep",
                0,
                60000,
                400,
            ),
            int(
                "sleep_cap_ms",
                "Sleep cap (ms)",
                "Longest Sleep emitted",
                0,
                600000,
                3000,
            ),
            int(
                "font_size",
                "Font size",
                "Set FontSize in the tape header",
                6,
                96,
                14,
            ),
            OptionSpec {
                key: "output",
                label: "Output name",
                help: "Name of the file the tape asks VHS to write",
                kind: OptKind::Text,
                default: OptValue::Text("demo.gif".into()),
            },
        ]
    }
    fn requires(&self) -> Requires {
        Requires::INPUT
    }

    fn export(
        &self,
        rec: &Recording,
        opts: &Options,
        out: &mut dyn Write,
        progress: &dyn Progress,
    ) -> Result<ExportReport, ExportError> {
        if !rec.sidecar.has_input {
            return Err(ExportError::NotPossible(
                "vhs export is not possible: this recording has no input events".into(),
            ));
        }
        let (type_gap, font_size) = (
            opts.int("type_gap_ms") as f64 / 1000.0,
            opts.int("font_size") as u32,
        );
        let mut tape = Tape {
            lines: Vec::new(),
            commands: 0,
            last: None,
            min_sleep: opts.int("min_sleep_ms") as f64,
            cap: opts.int("sleep_cap_ms") as f64,
        };
        let mut report = ExportReport::default();
        self.header(rec, opts, font_size, &mut tape)?;

        let events = rec.events()?;
        let total = events.len().max(1);
        let mut dec = Decoder::default();
        let mut run: Vec<(f64, char)> = Vec::new();
        let mut hidden = false;
        let flush = |tape: &mut Tape, run: &mut Vec<(f64, char)>| {
            if run.is_empty() {
                return;
            }
            let text: String = run.iter().map(|r| r.1).collect();
            let (first, last) = (run[0].0, run[run.len() - 1].0);
            tape.gap(first);
            let speed = if run.len() > 1 {
                let mean = ((last - first) * 1000.0 / (run.len() - 1) as f64)
                    .round()
                    .max(1.0);
                format!("@{mean}ms")
            } else {
                String::new()
            };
            for q in quote_segments(&text) {
                tape.cmd(format!("Type{speed} {q}"));
            }
            tape.last = Some(last);
            run.clear();
        };

        for (n, ev) in events.iter().enumerate() {
            if n % 256 == 0 {
                if progress.cancelled() {
                    return Err(ExportError::Cancelled);
                }
                progress.report(n as f32 / total as f32);
            }
            match &ev.kind {
                EventKind::Marker(l) if l == PAUSED_MARKER => {
                    flush(&mut tape, &mut run);
                    tape.gap(ev.time);
                    tape.note("input was not recorded here (echo off); VHS hides this span");
                    tape.cmd("Hide".into());
                    tape.note("add the hidden input here: Type \"...\" then Enter");
                    hidden = true;
                }
                EventKind::Input(s) => {
                    let mut keys = Vec::new();
                    let mut dropped = Vec::new();
                    dec.feed(s, &mut keys, &mut dropped);
                    for d in dropped {
                        *report.dropped.entry(d).or_default() += 1;
                    }
                    if hidden && !keys.is_empty() {
                        flush(&mut tape, &mut run);
                        tape.cmd("Show".into());
                        hidden = false;
                    }
                    for k in keys {
                        match k {
                            Key::Char(c) => {
                                if let Some(&(prev, _)) = run.last() {
                                    if ev.time - prev > type_gap {
                                        flush(&mut tape, &mut run);
                                    }
                                }
                                run.push((ev.time, c));
                            }
                            Key::Paste(text) => {
                                flush(&mut tape, &mut run);
                                tape.gap(ev.time);
                                let mut lines = text
                                    .replace('\r', "")
                                    .split('\n')
                                    .map(str::to_string)
                                    .collect::<Vec<_>>();
                                let last = lines.pop().unwrap_or_default();
                                for l in lines {
                                    for q in quote_segments(&l) {
                                        tape.cmd(format!("Type {q}"));
                                    }
                                    tape.cmd("Enter".into());
                                }
                                for q in quote_segments(&last) {
                                    tape.cmd(format!("Type {q}"));
                                }
                            }
                            other => {
                                flush(&mut tape, &mut run);
                                tape.gap(ev.time);
                                if let Some(c) = other.command() {
                                    tape.cmd(c);
                                }
                            }
                        }
                    }
                }
                _ => {}
            }
        }
        flush(&mut tape, &mut run);
        if hidden {
            tape.cmd("Show".into());
        }

        report
            .warnings
            .push("Output is regenerated by VHS and may differ from the recorded session".into());
        if !report.dropped.is_empty() {
            let list: Vec<_> = report
                .dropped
                .iter()
                .map(|(k, v)| format!("{k} x{v}"))
                .collect();
            report
                .warnings
                .push(format!("dropped: {}", list.join(", ")));
        }
        for l in &tape.lines {
            writeln!(out, "{l}")?;
        }
        progress.report(1.0);
        report.lines = tape.commands;
        Ok(report)
    }
}

impl Vhs {
    fn header(
        &self,
        rec: &Recording,
        opts: &Options,
        font_size: u32,
        tape: &mut Tape,
    ) -> Result<(), ExportError> {
        let sc = &rec.sidecar;
        tape.note(&format!(
            "Generated by microterm from recording {} ({})",
            sc.id, sc.title
        ));
        tape.note("Output is regenerated by VHS and may differ from the recorded session.");
        let name = opts.text("output");
        if name.is_empty() || name.contains(char::is_whitespace) {
            tape.cmd(format!(
                "Output {}",
                quote_segments(name)
                    .into_iter()
                    .next()
                    .unwrap_or_else(|| "\"demo.gif\"".into())
            ));
        } else {
            tape.cmd(format!("Output {name}"));
        }
        let proc = std::path::Path::new(&sc.origin.process)
            .file_name()
            .and_then(|s| s.to_str())
            .unwrap_or("")
            .trim_start_matches('-')
            .to_string();
        if SHELLS.contains(&proc.as_str()) {
            tape.cmd(format!("Set Shell \"{proc}\""));
        } else {
            tape.note("process is not a known shell; using bash");
            tape.cmd("Set Shell \"bash\"".into());
        }
        tape.cmd(format!("Set FontSize {font_size}"));
        if !sc.font.is_empty() && !sc.font.contains('"') {
            tape.cmd(format!("Set FontFamily \"{}\"", sc.font));
        }
        let fs = f64::from(font_size);
        let w = (f64::from(sc.cols) * fs * CELL_W_EM).ceil() as u32 + 2 * PADDING;
        let h = (f64::from(sc.rows) * (fs * CELL_H_EM).ceil()) as u32 + 2 * PADDING;
        tape.cmd(format!("Set Width {w}"));
        tape.cmd(format!("Set Height {h}"));
        tape.cmd(format!("Set Padding {PADDING}"));
        if let Some(t) = KNOWN_THEMES
            .iter()
            .find(|t| t.eq_ignore_ascii_case(&sc.theme))
        {
            tape.cmd(format!("Set Theme \"{t}\""));
        } else if !sc.theme.is_empty() {
            tape.note(&format!("theme \"{}\" is not known to VHS", sc.theme));
        }
        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::{default_options, find, testutil, NoProgress};
    use mt_record::Writer;
    use std::fs::File;

    fn tape_of(build: impl FnOnce(&mut Writer<File>)) -> (String, ExportReport) {
        let d = tempfile::tempdir().unwrap();
        let rec = testutil::recording(d.path(), true, build);
        let e = find("vhs").unwrap();
        let o = default_options(e, &Default::default());
        let mut out = Vec::new();
        let r = e.export(&rec, &o, &mut out, &NoProgress).unwrap();
        (String::from_utf8(out).unwrap(), r)
    }

    /// The tape without header lines (everything after `Set Padding`).
    fn body(build: impl FnOnce(&mut Writer<File>)) -> Vec<String> {
        let (t, _) = tape_of(build);
        let mut it = t.lines().skip_while(|l| !l.starts_with("Set Padding"));
        it.next();
        it.map(str::to_string).collect()
    }

    #[test]
    fn typed_run_uses_mean_gap_and_enter() {
        let b = body(|w| {
            for (i, c) in ["l", "s", " ", "-", "l"].iter().enumerate() {
                w.input(1.0 + i as f64 * 0.1, c.as_bytes()).unwrap();
            }
            w.input(1.5, b"\r").unwrap();
        });
        assert_eq!(b, ["Type@100ms \"ls -l\"", "Enter"]);
    }

    #[test]
    fn single_key_has_no_speed_and_gaps_make_sleeps() {
        let b = body(|w| {
            w.input(1.0, b"a").unwrap();
            w.input(1.3, b"b").unwrap(); // 300 ms: new Type, below min sleep
            w.input(2.0, b"c").unwrap(); // 700 ms: Sleep
            w.input(30.0, b"d").unwrap(); // capped
        });
        assert_eq!(
            b,
            [
                "Type \"a\"",
                "Type \"b\"",
                "Sleep 700ms",
                "Type \"c\"",
                "Sleep 3000ms",
                "Type \"d\""
            ]
        );
    }

    #[test]
    fn named_keys_and_ctrl() {
        let b = body(|w| {
            w.input(
                1.0,
                b"\x7f\t\x1b[A\x1b[B\x1b[C\x1b[D\x1b[H\x1b[F\x1b[5~\x1b[6~\x1b[3~",
            )
            .unwrap();
            w.input(1.0, b"\x1bOA\x1bOH\x1b[1~\x1b[4~\x03\x01\x1a\x1b")
                .unwrap();
        });
        assert_eq!(
            b,
            [
                "Backspace",
                "Tab",
                "Up",
                "Down",
                "Right",
                "Left",
                "Home",
                "End",
                "PageUp",
                "PageDown",
                "Delete",
                "Up",
                "Home",
                "Home",
                "End",
                "Ctrl+C",
                "Ctrl+A",
                "Ctrl+Z",
                "Escape"
            ]
        );
    }

    #[test]
    fn quotes_pick_a_free_delimiter_and_split_when_needed() {
        assert_eq!(quote_segments("a\"b"), ["'a\"b'"]);
        assert_eq!(quote_segments("a\"b'c"), ["`a\"b'c`"]);
        let segs = quote_segments("\"x'y`z");
        assert!(segs.len() >= 2);
        for s in &segs {
            let q = s.chars().next().unwrap();
            assert!(!s[1..s.len() - 1].contains(q), "{s}");
        }
        let joined: String = segs.iter().map(|s| &s[1..s.len() - 1]).collect();
        assert_eq!(joined, "\"x'y`z");
        assert_eq!(quote_segments("back\\slash"), ["\"back\\slash\""]);
    }

    #[test]
    fn bracketed_paste_is_one_type_per_line() {
        let b = body(|w| w.input(1.0, b"\x1b[200~echo hi\nls\x1b[201~").unwrap());
        assert_eq!(b, ["Type \"echo hi\"", "Enter", "Type \"ls\""]);
    }

    #[test]
    fn unknown_input_is_dropped_and_reported() {
        let (t, r) = tape_of(|w| {
            w.input(1.0, b"\x1b[<0;5;5M\x1b[I\x1b[99z\x1bxa").unwrap();
        });
        assert!(t.contains("Type \"a\""));
        assert_eq!(r.dropped["mouse report"], 1);
        assert_eq!(r.dropped["focus report"], 1);
        assert_eq!(r.dropped["unknown CSI"], 1);
        assert_eq!(r.dropped["Alt+key"], 1);
        assert!(r.warnings.iter().any(|w| w.contains("regenerated by VHS")));
    }

    #[test]
    fn redacted_span_is_hidden() {
        let b = body(|w| {
            w.input(1.0, b"sudo ls\r").unwrap();
            w.marker(1.1, PAUSED_MARKER).unwrap();
            w.input(5.0, b"x").unwrap();
        });
        let pos = |s: &str| b.iter().position(|l| l == s).unwrap();
        assert!(pos("Hide") < pos("Show"));
        assert!(b.iter().any(|l| l.starts_with('#')));
        assert_eq!(b.last().unwrap(), "Type \"x\"");
    }

    #[test]
    fn header_maps_the_recording() {
        let (t, _) = tape_of(|w| w.input(1.0, b"a").unwrap());
        assert!(t.contains("Output demo.gif"), "{t}");
        assert!(t.contains("Set Shell \"bash\""));
        assert!(t.contains("Set FontSize 14"));
        assert!(t.contains("Set Width 712"), "{t}"); // 80 * 14 * 0.6 = 672 + 2 * 20
        assert!(t.contains("Set Height 448"), "{t}"); // 24 * ceil(14 * 1.2) = 408 + 2 * 20
    }
}
